// Sentientia LMS PWA — iOS install hint — Phase B.3.d.
// Detects Safari iOS users who haven't added the site to home screen,
// shows a dismissible banner explaining the Share -> Add to Home Screen
// flow. iOS only enables Web Push when the PWA is installed to the
// home screen, so the subscribe button in preferences.php is
// effectively a no-op until they do this.
//
// Banner is built with createElement + textContent (never innerHTML)
// so passed-in labels are treated as PLAIN TEXT — no XSS surface even
// if the calling template misbehaves.
define('local_sentientia_pwa/ios_install_hint', [], function() {
    'use strict';

    var DISMISS_KEY = 'sentientia_pwa_ios_hint_dismissed';
    var BANNER_ID = 'sentientia-pwa-ios-hint';

    function isIosSafari() {
        var ua = window.navigator.userAgent || '';
        var isIos = /iPhone|iPad|iPod/i.test(ua) ||
            (/Macintosh/i.test(ua) && 'ontouchend' in document);
        if (!isIos) { return false; }
        if (/CriOS|FxiOS|EdgiOS|OPiOS/i.test(ua)) { return false; }
        return /Safari/i.test(ua);
    }

    function isStandalone() {
        return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
            || (window.navigator.standalone === true);
    }

    function wasDismissed() {
        try {
            return window.localStorage.getItem(DISMISS_KEY) === '1';
        } catch (e) {
            return false;
        }
    }

    function markDismissed() {
        try {
            window.localStorage.setItem(DISMISS_KEY, '1');
        } catch (e) { /* private mode */ }
    }

    function createTextNode(tag, text, className) {
        var el = document.createElement(tag);
        el.textContent = text;  // SAFE — never use innerHTML
        if (className) { el.className = className; }
        return el;
    }

    function buildBanner(labels) {
        var div = document.createElement('div');
        div.id = BANNER_ID;
        div.className = 'alert alert-info d-flex align-items-start mb-3';
        div.setAttribute('role', 'alert');

        var content = document.createElement('div');
        content.className = 'flex-grow-1';

        content.appendChild(createTextNode('strong', labels.title));
        content.appendChild(createTextNode('p', labels.body, 'mb-1 mt-1'));

        var ol = document.createElement('ol');
        ol.className = 'mb-0 small';
        ol.appendChild(createTextNode('li', labels.step1));
        ol.appendChild(createTextNode('li', labels.step2));
        ol.appendChild(createTextNode('li', labels.step3));
        content.appendChild(ol);

        div.appendChild(content);

        var dismissBtn = document.createElement('button');
        dismissBtn.type = 'button';
        dismissBtn.className = 'btn-close ms-2';
        dismissBtn.setAttribute('aria-label', labels.dismiss || 'Dismiss');
        dismissBtn.addEventListener('click', function() {
            markDismissed();
            if (div.parentNode) {
                div.parentNode.removeChild(div);
            }
        });
        div.appendChild(dismissBtn);

        return div;
    }

    function init(labels) {
        if (!isIosSafari()) { return; }
        if (isStandalone()) { return; }
        if (wasDismissed()) { return; }

        labels = labels || {
            title: 'Install Sentientia LMS to enable push notifications',
            body: 'On iOS Safari, push notifications only work when this site is added to your home screen:',
            step1: 'Tap the Share button at the bottom of the screen.',
            step2: 'Scroll down and choose "Add to Home Screen".',
            step3: 'Open Sentientia LMS from your home screen and try Enable notifications again.',
            dismiss: 'Dismiss'
        };

        var anchor = document.querySelector('.sentientia-pwa-subscribe')
            || document.querySelector('#region-main')
            || document.querySelector('main')
            || document.body;
        if (!anchor) { return; }

        anchor.parentNode.insertBefore(buildBanner(labels), anchor);
    }

    return {
        init: init,
        _isIosSafari: isIosSafari,
        _isStandalone: isStandalone
    };
});
